 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = max((c for c in counts if c != bg), key=lambda c: counts[c])

    # A repeated 3x3 cross is a signal to extend the corresponding pattern
    # across the remaining cells of its row in marker color 1.
    cross = [[1, 0, 1], [1, 1, 1], [1, 0, 1]]
    for r in range(h - 2):
        if [[grid[r+i][j] == fg for j in range(3, 6)] for i in range(3)] == cross:
            for i in range(3):
                for c in range(6, w):
                    if grid[r+i][c] == fg:
                        break
                    out[r+i][c] = 1
            break

    # In the line-pattern variant, extend a leading foreground run over the
    # blank suffix (the form in demos 1/4).
    for r, row in enumerate(grid):
        if row[0] != fg:
            continue
        end = 0
        while end < w and row[end] == fg:
            end += 1
        if end < w and all(v == bg for v in row[end:]):
            for c in range(end, w):
                out[r][c] = 1
            break
    return out
