 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # In the examples, repeated 3x3 glyphs are paired with a row of their
    # copy. The copy starts where the source ends; paint the source's blank
    # extension with color 1 while leaving other motif rows unchanged.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])

    # Look for a multi-row periodic glyph band. If a row ends with an aligned
    # three-cell foreground pattern and blank tail, extend the final pattern.
    for r, row in enumerate(grid):
        last = max((c for c, v in enumerate(row) if v == fg), default=-1)
        if last < 0 or last >= w - 1 or not all(v == bg for v in row[last + 1:]):
            continue
        # A valid continuation is supported by the row above/below at the same
        # final motif position, as in the repeated three-row glyphs.
        if r > 0 and grid[r - 1][last] == fg:
            for c in range(last + 1, w):
                out[r][c] = 1
            return out
        if r + 1 < h and grid[r + 1][last] == fg:
            for c in range(last + 1, w):
                out[r][c] = 1
            return out

    # Single-row horizontal bar examples: complete its blank suffix.
    for r, row in enumerate(grid):
        if row[0] != fg:
            continue
        end = 0
        while end < w and row[end] == fg:
            end += 1
        if end < w and all(v == bg for v in row[end:]):
            for c in range(end, w):
                out[r][c] = 1
            return out
    return out
