    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])

    # Find separated horizontal pattern bands, then transfer the populated
    # part of one band into the corresponding blank part of its partner.
    bands = []
    r = 0
    while r < h:
        if any(v == fg for v in grid[r]):
            start = r
            while r < h and any(v == fg for v in grid[r]):
                r += 1
            bands.append((start, r))
        else:
            r += 1
    for (a, b), (c, d) in zip(bands, bands[1:]):
        if b - a != d - c or b - a < 2:
            continue
        # Copy the pattern from whichever band has content farther to the
        # right. Original foreground stays; source background becomes marker 1.
        right_a = max((j for row in grid[a:b] for j, v in enumerate(row) if v == fg), default=-1)
        right_b = max((j for row in grid[c:d] for j, v in enumerate(row) if v == fg), default=-1)
        if right_a == right_b:
            continue
        src, dst = (a, c) if right_a > right_b else (c, a)
        src_right = max(right_a, right_b)
        for i in range(b - a):
            for j in range(w):
                if grid[dst + i][j] == bg and j <= src_right:
                    out[dst + i][j] = 1 if grid[src + i][j] == bg else fg
        return out

    # Single horizontal-bar demonstrations: extend the incomplete bar suffix.
