    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The top and lower four-row strips encode the same repeated 3-column
    # pattern family. Continue the lower strip by repeating the top strip's
    # established rightmost motif; background slots in the continuation are
    # shown in marker color 1.
